#include <expected>
#include <iostream>
#include <string>

int main() {
    std::expected<int, std::string> value{6};
    auto doubled = value.transform([](int number) { return number * 2; });
    auto next = doubled.and_then(
        [](int number) -> std::expected<int, std::string> { return number + 1; });
    std::expected<int, std::string> failed{std::unexpected(std::string{"bad"})};
    auto labeled = failed.transform_error(
        [](const std::string &error) { return "Error: " + error; });
    auto recovered = labeled.or_else(
        [](const std::string &) -> std::expected<int, std::string> { return 0; });
    std::cout << next.value() << "\n"
              << labeled.error() << "\n"
              << recovered.value() << "\n";
}
